"""Regenerate docs/configuration.md from the ``Settings`` model.

uv run python scripts/gen_config_docs.py
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

from pydantic import SecretStr

from ticket2pr.config import Settings

DOC = Path(__file__).resolve().parent.parent / "docs" / "configuration.md"

HEADER = """\
# Configuration

<!-- Generated by scripts/gen_config_docs.py from ticket2pr.config.Settings. Do not edit. -->

Every setting is an environment variable with the `T2P_` prefix, or a line in a `.env` file
in the working directory. Lists and mappings are JSON, e.g.
`T2P_REPOS='{"PROJ": "acme/api"}'`. The Claude API key is also accepted under its usual
name, `ANTHROPIC_API_KEY`, in the environment or in `.env`.

| Variable | Default | Description |
|---|---|---|
"""


def _default(value: object) -> str:
    if isinstance(value, SecretStr):
        return "*(secret)*"
    if isinstance(value, (list, dict)):
        return f"`{json.dumps(value)}`"
    if isinstance(value, bool):
        return f"`{str(value).lower()}`"
    return f"`{value}`" if value not in ("", None) else "*(empty)*"


def render() -> str:
    rows = []
    for name, field in Settings.model_fields.items():
        default = field.get_default(call_default_factory=True)
        description = (field.description or "").replace("|", "\\|")
        rows.append(f"| `T2P_{name.upper()}` | {_default(default)} | {description} |")
    return HEADER + "\n".join(rows) + "\n"


if __name__ == "__main__":
    if "--check" in sys.argv:
        sys.exit(0 if DOC.read_text(encoding="utf-8") == render() else 1)
    DOC.write_text(render(), encoding="utf-8")
